import re


class StackUnderflowError(Exception):
    pass


_NUMBER_RE = re.compile(r"-?\d+")


def _is_number(token):
    return _NUMBER_RE.fullmatch(token) is not None


def _check_stack(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")


def _add(stack):
    _check_stack(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a + b)


def _sub(stack):
    _check_stack(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a - b)


def _mul(stack):
    _check_stack(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a * b)


def _div(stack):
    _check_stack(stack, 2)
    b = stack.pop()
    a = stack.pop()
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    q, r = divmod(a, b)
    if r != 0 and (a < 0) != (b < 0):
        # Truncate toward zero instead of flooring.
        q += 1
    stack.append(q)


def _dup(stack):
    _check_stack(stack, 1)
    stack.append(stack[-1])


def _drop(stack):
    _check_stack(stack, 1)
    stack.pop()


def _swap(stack):
    _check_stack(stack, 2)
    stack[-1], stack[-2] = stack[-2], stack[-1]


def _over(stack):
    _check_stack(stack, 2)
    stack.append(stack[-2])


_BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def _compile(token, user_words):
    """Translate a token into a list of executable actions.

    Known words are expanded in place so that definitions capture the
    meaning of the words they reference at the time they are defined.
    Unknown words are kept by name and resolved when executed.
    """
    if _is_number(token):
        return [int(token)]
    name = token.lower()
    if name in user_words:
        return list(user_words[name])
    if name in _BUILTINS:
        return [_BUILTINS[name]]
    return [name]


def _run(actions, stack, user_words):
    for action in actions:
        if isinstance(action, int):
            stack.append(action)
        elif isinstance(action, str):
            if action in user_words:
                _run(user_words[action], stack, user_words)
            else:
                raise ValueError("undefined operation")
        else:
            action(stack)


def evaluate(input_data):
    stack = []
    user_words = {}

    for line in input_data:
        tokens = line.split()
        if tokens and tokens[0] == ":":
            if len(tokens) < 2:
                raise ValueError("illegal operation")
            name = tokens[1].lower()
            if _is_number(name):
                raise ValueError("illegal operation")
            body = []
            for token in tokens[2:]:
                if token == ";":
                    break
                body.extend(_compile(token, user_words))
            user_words[name] = body
            continue

        for token in tokens:
            if _is_number(token):
                stack.append(int(token))
                continue
            name = token.lower()
            if name in user_words:
                _run(user_words[name], stack, user_words)
            elif name in _BUILTINS:
                _BUILTINS[name](stack)
            else:
                raise ValueError("undefined operation")

    return stack

